const COA_GREEN_ALLOWLIST = ['lot_id','filename','sha256','moisture_pct','mesh_pass','spec_moisture_max','spec_mesh_required','salmonella_absent','spec_salmonella_required','tpc_cfu','spec_tpc_max','pyruvic_umol','spec_pyruvic_required','spec_pyruvic_min'];
const RED_FORBIDDEN = ['bytes','pdf','path','file_bytes','nextcloud_folder_path','vault_href'];
function assertAllowlist(payload) {
  if (payload == null || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('payload required');
  for (const key of Object.keys(payload)) {
    if (RED_FORBIDDEN.includes(key)) throw new Error('RED COA key forbidden: ' + key);
    if (!COA_GREEN_ALLOWLIST.includes(key)) throw new Error('unknown COA key forbidden: ' + key);
    if (payload[key] != null && typeof payload[key] === 'object') throw new Error('nested objects forbidden');
  }
}
function assertBasename(name) {
  if (typeof name !== 'string' || !name) throw new Error('filename must be a basename with no path');
  if (name.includes('/') || name.includes('\\') || name.includes('..') || name.includes('\0')) {
    throw new Error('filename must be a basename with no path');
  }
}
const item = $input.first();
if (item.binary && Object.keys(item.binary).length) throw new Error('RED binary payload forbidden');
const input = item.json;
const headers = input.headers ?? {};
const provided = headers['x-sattva-webhook-hmac'] ?? headers['X-Sattva-Webhook-Hmac'];
const expected = $env.N8N_WEBHOOK_HMAC;
if (typeof expected !== 'string' || !expected || typeof provided !== 'string' || provided !== expected) {
  throw new Error('invalid x-sattva-webhook-hmac');
}
const payload = input.body ?? input;
assertAllowlist(payload);
if (typeof payload.lot_id !== 'number' || !Number.isInteger(payload.lot_id) || payload.lot_id < 1) throw new Error('lot_id must be a positive integer');
assertBasename(payload.filename);
if (typeof payload.sha256 !== 'string' || !/^[a-f0-9]{64}$/i.test(payload.sha256)) throw new Error('sha256 must be 64 hex characters');
if (typeof payload.moisture_pct !== 'number' || !Number.isFinite(payload.moisture_pct)) throw new Error('moisture_pct must be a number');
if (typeof payload.spec_moisture_max !== 'number' || !Number.isFinite(payload.spec_moisture_max)) throw new Error('spec_moisture_max must be a number');
if (typeof payload.mesh_pass !== 'boolean') throw new Error('mesh_pass must be boolean');
if (typeof payload.spec_mesh_required !== 'boolean') throw new Error('spec_mesh_required must be boolean');
if (typeof payload.salmonella_absent !== 'boolean') throw new Error('salmonella_absent must be boolean');
if (typeof payload.spec_salmonella_required !== 'boolean') throw new Error('spec_salmonella_required must be boolean');
if (typeof payload.tpc_cfu !== 'number' || !Number.isFinite(payload.tpc_cfu)) throw new Error('tpc_cfu must be a number');
if (typeof payload.spec_tpc_max !== 'number' || !Number.isFinite(payload.spec_tpc_max)) throw new Error('spec_tpc_max must be a number');
if (typeof payload.pyruvic_umol !== 'number' || !Number.isFinite(payload.pyruvic_umol)) throw new Error('pyruvic_umol must be a number');
if (typeof payload.spec_pyruvic_required !== 'boolean') throw new Error('spec_pyruvic_required must be boolean');
if (typeof payload.spec_pyruvic_min !== 'number' || !Number.isFinite(payload.spec_pyruvic_min)) throw new Error('spec_pyruvic_min must be a number');
return [{ json: {
  lot_id: payload.lot_id,
  filename: payload.filename,
  sha256: payload.sha256.toLowerCase(),
  moisture_pct: payload.moisture_pct,
  mesh_pass: payload.mesh_pass,
  spec_moisture_max: payload.spec_moisture_max,
  spec_mesh_required: payload.spec_mesh_required,
  salmonella_absent: payload.salmonella_absent,
  spec_salmonella_required: payload.spec_salmonella_required,
  tpc_cfu: payload.tpc_cfu,
  spec_tpc_max: payload.spec_tpc_max,
  pyruvic_umol: payload.pyruvic_umol,
  spec_pyruvic_required: payload.spec_pyruvic_required,
  spec_pyruvic_min: payload.spec_pyruvic_min
} }];
